  INSERT INTO gap_analysis_frameworks (nome, nome_en, descricao, descricao_en, versao, tipo_framework, tipo, is_template, empresa_id)
  INSERT INTO gap_analysis_requirements (framework_id, codigo, titulo, titulo_en, descricao, categoria, categoria_en, ordem, peso) VALUES
  (fw,'Art. 2º','Política de segurança cibernética implementada','Cybersecurity policy implemented','A instituição implementa e mantém política de segurança cibernética baseada em princípios de confidencialidade, integridade e disponibilidade dos dados e sistemas.','Política de segurança cibernética','Cybersecurity policy',1,3),
  (fw,'Art. 3º, I','Objetivos de segurança cibernética definidos','Cybersecurity objectives defined','A política define os objetivos de segurança cibernética da instituição.','Política de segurança cibernética','Cybersecurity policy',2,2),
  (fw,'Art. 3º, II','Procedimentos e controles para reduzir a vulnerabilidade a incidentes','Procedures and controls to reduce exposure to incidents','Autenticação, criptografia, prevenção e detecção de intrusão, prevenção de vazamento de informações, testes e varreduras de vulnerabilidades, proteção contra software malicioso, rastreabilidade, controle de acesso, segmentação de rede e cópias de segurança.','Política de segurança cibernética','Cybersecurity policy',3,3),
  (fw,'Art. 3º, III','Controles específicos de rastreabilidade da informação','Information traceability controls','Controles que garantam a rastreabilidade da informação sensível, inclusive para prestadores de serviços.','Política de segurança cibernética','Cybersecurity policy',4,2),
  (fw,'Art. 3º, IV','Registro, análise de causa e impacto de incidentes relevantes','Recording, root-cause and impact analysis of relevant incidents','Procedimentos para registrar e analisar a causa e o impacto de incidentes relevantes, incluindo os ocorridos em prestadores de serviços.','Gestão de incidentes','Incident management',5,3),
  (fw,'Art. 3º, V','Classificação de dados e informações por relevância','Data classification by relevance','Diretrizes para classificar dados e informações quanto à relevância e para elaborar cenários de incidentes considerados nos testes de continuidade.','Política de segurança cibernética','Cybersecurity policy',6,2),
  (fw,'Art. 3º, VI','Parâmetros para avaliar a relevância dos incidentes','Criteria to assess incident relevance','Critérios definidos para avaliar a relevância dos incidentes de segurança cibernética.','Gestão de incidentes','Incident management',7,2),
  (fw,'Art. 3º, VII','Cultura de segurança cibernética','Cybersecurity culture','Mecanismos para disseminar a cultura de segurança: treinamentos, avaliações periódicas e informação a clientes e usuários sobre precauções no uso de produtos e serviços.','Pessoas e cultura','People and culture',8,2),
  (fw,'Art. 3º, VIII','Compartilhamento de informações sobre incidentes relevantes','Sharing information about relevant incidents','Iniciativas para compartilhar com outras instituições informações sobre incidentes relevantes.','Gestão de incidentes','Incident management',9,1),
  (fw,'Art. 4º','Política compatível com porte, perfil de risco e complexidade','Policy proportionate to size, risk profile and complexity','A política considera o porte, o perfil de risco, o modelo de negócio, a complexidade das operações e a sensibilidade dos dados.','Governança','Governance',10,2),
  (fw,'Art. 6º','Plano de ação e de resposta a incidentes','Incident action and response plan','Plano com as ações para adequar estruturas e processos à política, rotinas e procedimentos de prevenção e resposta, e a área responsável pelo registro e controle dos incidentes relevantes.','Gestão de incidentes','Incident management',11,3),
  (fw,'Art. 7º','Diretor responsável pela segurança cibernética','Director responsible for cybersecurity','Indicação de diretor responsável pela política e pela execução do plano de ação e resposta a incidentes.','Governança','Governance',12,3),
  (fw,'Art. 8º','Relatório anual de implementação do plano','Annual report on plan implementation','Relatório anual (data-base 31 de dezembro) sobre a implementação do plano, a efetividade das ações, os incidentes relevantes e os testes de continuidade, apresentado ao comitê de risco e à diretoria até 31 de março.','Governança','Governance',13,3),
  (fw,'Art. 9º','Aprovação e revisão anual pela diretoria ou conselho','Board approval and annual review','Política e plano aprovados pelo conselho de administração ou pela diretoria, e revisados no mínimo anualmente.','Governança','Governance',14,3),
  (fw,'Art. 10','Divulgação da política','Policy communication','Política divulgada a funcionários e prestadores de serviços, com resumo das linhas gerais divulgado ao público.','Pessoas e cultura','People and culture',15,2),
  (fw,'Art. 11','Procedimentos para contratar processamento, armazenamento e nuvem','Procedures for outsourcing processing, storage and cloud','Procedimentos de contratação com adoção de práticas de governança corporativa e de gestão proporcionais à relevância do serviço e aos riscos.','Contratação de serviços e nuvem','Outsourcing and cloud',16,3),
  (fw,'Art. 12','Avaliação prévia do prestador de serviços','Prior assessment of the service provider','Verificação da capacidade do prestador: cumprimento da legislação, acesso aos dados, confidencialidade e integridade, aderência a certificações, segregação de dados e qualidade dos controles de acesso.','Contratação de serviços e nuvem','Outsourcing and cloud',17,3),
  (fw,'Art. 13','Serviços de computação em nuvem','Cloud computing services','Avaliação dos serviços de nuvem contratados (infraestrutura, plataforma ou software) e dos controles do prestador.','Contratação de serviços e nuvem','Outsourcing and cloud',18,2),
  (fw,'Art. 15','Comunicação prévia ao Banco Central de contratações relevantes','Prior notice to the Central Bank of relevant contracts','Comunicação ao Banco Central da contratação de serviços relevantes de processamento, armazenamento e nuvem, com os dados exigidos e prazo regulamentar.','Contratação de serviços e nuvem','Outsourcing and cloud',19,3),
  (fw,'Art. 16','Contratação de serviços no exterior','Outsourcing to providers abroad','Contratação no exterior apenas com acordo de cooperação entre o BACEN e as autoridades do país, previsão no contrato do acesso do BACEN e definição prévia dos países e regiões de armazenamento.','Contratação de serviços e nuvem','Outsourcing and cloud',20,3),
  (fw,'Art. 17','Cláusulas contratuais obrigatórias','Mandatory contract clauses','Contratos com cláusulas sobre a indicação dos países e regiões, segurança e segregação dos dados, acesso do BACEN, notificação de subcontratação, continuidade e transferência dos dados no encerramento.','Contratação de serviços e nuvem','Outsourcing and cloud',21,3),
  (fw,'Art. 19','Continuidade de negócios para incidentes relevantes','Business continuity for relevant incidents','Procedimentos de continuidade para tratar incidentes relevantes e interrupções de serviços contratados, com cenários de incidentes e testes periódicos.','Continuidade de negócios','Business continuity',22,3),
  (fw,'Art. 20','Comunicação tempestiva de incidentes relevantes ao Banco Central','Timely reporting of relevant incidents to the Central Bank','Comunicação ao BACEN dos incidentes relevantes e das interrupções de serviços relevantes que configurem situação de crise, com as providências de reinício das atividades.','Gestão de incidentes','Incident management',23,3),
  (fw,'Art. 23','Guarda da documentação por 5 anos','Five-year record retention','Documentação sobre a política, o plano, o relatório anual, os contratos e os incidentes mantida à disposição do BACEN pelo prazo de cinco anos.','Governança','Governance',24,2);
